import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ __launch_bounds__(256)
void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K,
    int split_k
) {
    constexpr int TILE_M = 64;
    constexpr int TILE_N = 64;
    constexpr int TILE_K = 16;
    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_K][TILE_N];
    const int tid = threadIdx.x;
    const int block_row = blockIdx.y * TILE_M;
    const int block_col = blockIdx.x * TILE_N;
    const int split_id = blockIdx.z;
    const int k_begin = (K * split_id) / split_k;
    const int k_end = (K * (split_id + 1)) / split_k;
    const int thread_row = (tid / 16) * 4;
    const int thread_col = (tid % 16) * 4;
    float acc[4][4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    for (int k0 = k_begin; k0 < k_end; k0 += TILE_K) {
        for (int idx = tid; idx < TILE_M * TILE_K + TILE_K * TILE_N; idx += 256) {
            if (idx < TILE_M * TILE_K) {
                const int r = idx / TILE_K;
                const int k = idx % TILE_K;
                const int global_r = block_row + r;
                const int global_k = k0 + k;
                As[r][k] =
                    (global_r < M && global_k < k_end)
                        ? A[(int64_t)global_r * K + global_k]
                        : 0.0f;
            } else {
                const int bidx = idx - TILE_M * TILE_K;
                const int k = bidx / TILE_N;
                const int c = bidx % TILE_N;
                const int global_k = k0 + k;
                const int global_c = block_col + c;
                Bs[k][c] =
                    (global_k < k_end && global_c < N)
                        ? B[(int64_t)global_k * N + global_c]
                        : 0.0f;
            }
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            float a[4];
            float b[4];
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                a[i] = As[thread_row + i][k];
            }
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                b[j] = Bs[k][thread_col + j];
            }
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    acc[i][j] += a[i] * b[j];
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        const int row = block_row + thread_row + i;
        if (row < M) {
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                const int col = block_col + thread_col + j;
                if (col < N) {
                    atomicAdd(&C[(int64_t)row * N + col], acc[i][j]);
                }
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "incompatible matrix dimensions");

    A = A.contiguous();
    B = B.contiguous();

    const int M = static_cast<int>(A.size(0));
    const int K = static_cast<int>(A.size(1));
    const int N = static_cast<int>(B.size(1));

    auto C = torch::empty(
        {M, N},
        torch::TensorOptions()
            .device(A.device())
            .dtype(torch::kFloat32)
    );

    const int split_k = (K > 16384) ? 32 : 1;
    const dim3 block(256);
    const dim3 grid(
        (N + 63) / 64,
        (M + 63) / 64,
        split_k
    );

    cudaStream_t stream = at::cuda::getCurrentCUDAStream(A.device().index());

    cudaMemsetAsync(
        C.data_ptr<float>(),
        0,
        static_cast<size_t>(M) * N * sizeof(float),
        stream
    );

    matmul_kernel<<<grid, block, 0, stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        N,
        K,
        split_k
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
"""

_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""
_matmul_cuda = load_inline(
    name="custom_large_k_matmul",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matmul_cuda"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matmul_cuda.matmul_cuda(A, B)

